<?php
/** TEMP PS S1685 me — DEPLOY naujas mu-plugin petshop-sutikimai.php v1.0.0 (kasos soft opt-out); token_get_all; heartbeat; rollback; + testinės prekės id. */
add_action('init', function(){
  if (!isset($_GET['ps_s1685me'])) return; global $wpdb; $p=$wpdb->prefix; $o=array('v'=>'S1685 me'); $f=WPMU_PLUGIN_DIR.'/petshop-sutikimai.php';
  if(file_exists($f)||class_exists('Petshop_Sutikimai')){ $o['STOP']='vardas/klasė užimti'; echo json_encode($o); exit; }
  $n=base64_decode(''); if(md5($n)!=='e60379335f0e1c777c4137276c83689a'){ $o['STOP']='md5 payload'; echo json_encode($o); exit; }
  try { token_get_all($n, TOKEN_PARSE); } catch (Throwable $e) { $o['STOP']='ParseError: '.$e->getMessage(); echo json_encode($o); exit; }
  file_put_contents($f,$n); if(function_exists('opcache_invalidate')) opcache_invalidate($f,true); $o['md5']=md5_file($f);
  $hb=wp_remote_get(home_url('/'),array('timeout'=>20,'sslverify'=>false)); $code=is_wp_error($hb)?0:wp_remote_retrieve_response_code($hb); $o['heartbeat']=$code; if($code>=500||$code===0){ unlink($f); $o['ROLLBACK']='ištrinta'; echo json_encode($o); exit; }
  $o['test_preke']=$wpdb->get_results("SELECT ID,post_title,post_status FROM {$p}posts WHERE post_type='product' AND post_title LIKE '%test%' ORDER BY ID DESC LIMIT 3",ARRAY_A);
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o,JSON_UNESCAPED_UNICODE); exit;
});
